class Solution {
public:
    long long maximumTotalDamage(vector<int>& power) {
        map<int, int> cnt;
        for (int p : power) cnt[p]++;
        vector<long long> vals;
        vector<long long> total_gain;
        for (const auto& [v, c] : cnt) {
            vals.push_back(v);
            total_gain.push_back(1LL * v * c);
        }
        int m = vals.size();
        vector<long long> dp(m + 1, 0);
        for (int i = 0; i < m; ++i) {
            int idx = lower_bound(vals.begin(), vals.end(), vals[i] - 2) - vals.begin();
            dp[i + 1] = max(dp[i], dp[idx] + total_gain[i]);
        }
        return dp[m];
    }
};

class Solution {
    public long maximumTotalDamage(int[] power) {
        Map<Integer, Integer> cnt = new TreeMap<>();
        for (int p : power) cnt.put(p, cnt.getOrDefault(p, 0) + 1);
        int m = cnt.size();
        long[] vals = new long[m];
        long[] totalGain = new long[m];
        int ptr = 0;
        for (Map.Entry<Integer, Integer> e : cnt.entrySet()) {
            vals[ptr] = e.getKey();
            totalGain[ptr] = vals[ptr] * e.getValue();
            ptr++;
        }
        long[] dp = new long[m + 1];
        for (int i = 0; i < m; ++i) {
            int low = 0, high = i, best = 0;
            while (low < high) {
                int mid = (low + high) / 2;
                if (vals[mid] >= vals[i] - 2) high = mid;
                else low = mid + 1;
            }
            dp[i + 1] = Math.max(dp[i], dp[low] + totalGain[i]);
        }
        return dp[m];
    }
}

var maximumTotalDamage = function(power) {
    const cnt = new Map();
    for (const p of power) cnt.set(p, (cnt.get(p) || 0) + 1);
    const vals = Array.from(cnt.keys()).sort((a, b) => a - b);
    const m = vals.length;
    const dp = new BigInt64Array(m + 1);
    for (let i = 0; i < m; ++i) {
        const v = vals[i];
        const gain = BigInt(v) * BigInt(cnt.get(v));
        let low = 0, high = i;
        while (low < high) {
            const mid = (low + high) >> 1;
            if (vals[mid] >= v - 2) high = mid;
            else low = mid + 1;
        }
        const take = dp[low] + gain;
        dp[i + 1] = dp[i] > take ? dp[i] : take;
    }
    return Number(dp[m]);
};
